import { IWcBindable } from "../types.js";
import { WcsIoErrorInfo } from "./platformCapability.js";
import { deriveWebSocketErrorInfo, WCS_WEBSOCKET_ERROR_CODE } from "./websocketCapabilities.js";

// WebSocket readyState values. Hardcoded rather than read from the global
// WebSocket so the Core does not require WebSocket to exist at module load
// (referencing `WebSocket.CLOSED` in a field initializer evaluates at class
// definition time; tests inject a mock). Mirrors SseCore's SSE_CLOSED.
const WS_CONNECTING = 0;
const WS_OPEN = 1;
const WS_CLOSED = 3;

export interface WebSocketConnectOptions {
  protocols?: string | string[];
  autoReconnect?: boolean;
  reconnectInterval?: number;
  maxReconnects?: number;
  // How incoming binary frames are surfaced on `message`. "blob" (the platform
  // default) or "arraybuffer" for direct byte processing. Applied to every
  // socket this connection spawns, including auto-reconnects.
  binaryType?: BinaryType;
  // Milliseconds without a message after which an open connection is treated as lost (0 or
  // absent: never). A WebSocket does not notice a connection that died without being closed — a
  // laptop's sleep, a NAT or proxy that dropped it — and stays OPEN; the server must send a message
  // more often than this (a protocol-level ping frame is not seen by the page).
  staleAfter?: number;
}

export class WebSocketCore extends EventTarget {
  static wcBindable: IWcBindable = {
    protocol: "wc-bindable",
    version: 1,
    properties: [
      { name: "message", event: "wcs-ws:message", semantics: "event" },
      { name: "connected", event: "wcs-ws:connected-changed", semantics: "state" },
      { name: "loading", event: "wcs-ws:loading-changed", semantics: "state" },
      { name: "error", event: "wcs-ws:error", semantics: "state" },
      // Serializable failure taxonomy (stable code / phase / recoverable), or null.
      // Additive bindable output derived from `error` (invalid-argument / invalid-state
      // / connection-error); the existing `error` property/event are unchanged. Fires
      // wcs-ws:error-info-changed. No lane — WebSocket is a persistent session/monitor
      // node, not a competing operation.
      { name: "errorInfo", event: "wcs-ws:error-info-changed", semantics: "state" },
      { name: "readyState", event: "wcs-ws:readystate-changed", semantics: "state" },
    ],
    commands: [
      { name: "connect" },
      { name: "send" },
      { name: "close" },
    ],
  };

  private _target: EventTarget;
  private _ws: WebSocket | null = null;
  private _message: any = null;
  private _connected: boolean = false;
  private _loading: boolean = false;
  private _error: any = null;
  private _errorInfo: WcsIoErrorInfo | null = null;
  private _readyState: number = WS_CLOSED;

  // 自動再接続
  private _autoReconnect: boolean = false;
  private _reconnectInterval: number = 3000;
  private _maxReconnects: number = Infinity;
  private _reconnectCount: number = 0;
  private _reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private _url: string = "";
  private _protocols: string | string[] | undefined = undefined;
  private _binaryType: BinaryType = "blob";
  private _intentionalClose: boolean = false;
  // stale-after (ms, 0 = off): the time of the last open / message, and the watchdog's timer
  private _staleAfter: number = 0;
  private _lastActivity: number = 0;
  private _staleTimer: ReturnType<typeof setTimeout> | null = null;

  // Generation guard (§3.4): bumped on dispose() and at every connect(). A socket
  // event (open/message/error/close) or a scheduled reconnect that fires after
  // dispose / a superseding connect() carries a stale `gen` and MUST NOT write
  // state onto a torn-down element. A boolean flag is insufficient (dispose→observe
  // would let stale work slip through).
  private _gen = 0;
  // Generation captured when the current socket was opened. The shared socket
  // event handlers compare it against _gen to drop events from a superseded /
  // disposed connection.
  private _socketGen = 0;
  // SSR (§3.8): WebSocket is command-driven with no asynchronous probe to await,
  // so readiness is immediate.
  private _ready: Promise<void> = Promise.resolve();

  /**
   * Whether `[wcs/command-not-ready]` was said in this outage: a `send()` refused because the
   * element is not ready loses what it carried, and `error` alone told only a page that binds it.
   * Said once per outage (docs/v4-direction-2026-10.md, the I/O command policy): the socket opening
   * resets it. Once per element was once per page life — a route puts the same element back on
   * every entry, so the next outage's lost message went unsaid (docs/seam-apps.md, shift-desk).
   */
  private _toldNotReady = false;

  constructor(target?: EventTarget) {
    super();
    this._target = target ?? this;
  }

  get ready(): Promise<void> {
    return this._ready;
  }

  // Lifecycle (§3.5). WebSocket connections are command-driven (connect()), so
  // observe() is an idempotent no-op that resolves once ready; the Shell's
  // connectedCallback does not auto-establish a subscription here. dispose()
  // invalidates any in-flight socket / pending reconnect and closes the socket.
  observe(): Promise<void> {
    return this._ready;
  }

  dispose(): void {
    this._end(false);
  }

  /**
   * Closes like dispose() — the end is published at once — and says whether a connection was
   * open, opening or about to reopen (auto-reconnect). The Shell uses it when the page may enter
   * the back/forward cache, and reconnects on the way back.
   */
  suspend(): boolean {
    const live = this._ws !== null || this._reconnectTimer !== null;
    // A socket still connecting is closed at once here, not when it opens (see _stop): a page
    // with a WebSocket in use is not put in the back/forward cache, and a page about to be
    // frozen runs no listener that would close it later. Chromium's warning is the price.
    this._end(true);
    return live;
  }

  private _end(abortConnecting: boolean): void {
    this._gen++;
    this._stop(undefined, undefined, abortConnecting);
    // The socket's close event is dropped as stale (the generation moved) or, for a socket
    // still connecting, never reaches the core (it is let go), so the
    // connection's end is published here (timing-and-firing-contract §22): a route the
    // element leaves keeps its nodes — bindings included — for the next entry, and
    // state would keep showing a connection that is gone.
    this._publishClosed();
  }

  private _publishClosed(): void {
    this._setConnected(false);
    this._setLoading(false);
    this._setReadyState(WS_CLOSED);
  }

  get message(): any {
    return this._message;
  }

  get connected(): boolean {
    return this._connected;
  }

  get loading(): boolean {
    return this._loading;
  }

  get error(): any {
    return this._error;
  }

  /**
   * The last failure's serializable `WcsIoErrorInfo` (stable `code` / `phase` /
   * `recoverable`), or null. Additive wc-bindable property (event
   * `wcs-ws:error-info-changed`), derived from `error`; the existing `error`
   * property/event are unchanged.
   */
  get errorInfo(): WcsIoErrorInfo | null {
    return this._errorInfo;
  }

  get readyState(): number {
    return this._readyState;
  }

  // --- State setters with event dispatch ---

  private _setMessage(message: any): void {
    this._message = message;
    this._target.dispatchEvent(new CustomEvent("wcs-ws:message", {
      detail: message,
      bubbles: true,
    }));
  }

  private _setConnected(connected: boolean): void {
    this._connected = connected;
    this._target.dispatchEvent(new CustomEvent("wcs-ws:connected-changed", {
      detail: connected,
      bubbles: true,
    }));
  }

  private _setLoading(loading: boolean): void {
    this._loading = loading;
    this._target.dispatchEvent(new CustomEvent("wcs-ws:loading-changed", {
      detail: loading,
      bubbles: true,
    }));
  }

  // `code` is an explicit taxonomy discriminator (WCS_WEBSOCKET_ERROR_CODE), passed
  // only from the non-null failure call sites. It stays out of the public `error`
  // shape and is used solely to classify errorInfo without reverse-engineering the
  // heterogeneous `error` values (synthetic {message} / caught Error / raw Event).
  // The clear path passes null and no code.
  private _setError(error: any, code?: string): void {
    // Same-value guard (async-io-node-guidelines.md §3.3). `error` is state-ish,
    // so suppressing redundant null→null dispatches (every connect/send start
    // clears a usually-already-null error) avoids a spurious wcs-ws:error per
    // successful operation. Reference identity is sufficient: each failure builds
    // a fresh object (or the platform's own error Event), and the clear path
    // always passes null.
    if (this._error === error) return;
    this._error = error;
    // Keep the additive `errorInfo` taxonomy in sync with `error`: derive from the
    // explicit `code` (or null on clear). Fires before the `error` event so an
    // observer binding both sees the classification first, mirroring the io-node
    // family. Every non-null error carries a code (the clear path is the only
    // caller without one, and it is short-circuited here), so `code!` holds.
    this._commitErrorInfo(error === null ? null : deriveWebSocketErrorInfo(error, code!));
    this._target.dispatchEvent(new CustomEvent("wcs-ws:error", {
      detail: error,
      bubbles: true,
    }));
  }

  // Called only from _setError (which already same-value-guards on the error
  // reference), so errorInfo transitions exactly when error does — no separate
  // guard needed here.
  private _commitErrorInfo(info: WcsIoErrorInfo | null): void {
    this._errorInfo = info;
    this._target.dispatchEvent(new CustomEvent("wcs-ws:error-info-changed", {
      detail: info,
      bubbles: true,
    }));
  }

  private _setReadyState(readyState: number): void {
    this._readyState = readyState;
    this._target.dispatchEvent(new CustomEvent("wcs-ws:readystate-changed", {
      detail: readyState,
      bubbles: true,
    }));
  }

  // --- Public API ---

  connect(url: string, options: WebSocketConnectOptions = {}): void {
    // never-throw (§3.6): 引数バリデーション失敗は例外ではなく error プロパティに
    // 流し、サニタイズ値(なにもしない)を返す。command-token 経路（set trigger →
    // connect()）からの呼び出しが state 更新サイクルを壊さないようにする。
    if (!url) {
      this._setError({ message: "url is required." }, WCS_WEBSOCKET_ERROR_CODE.InvalidArgument);
      return;
    }

    // 新しい接続を開始するため世代を更新し、進行中のソケット/再接続を無効化する。
    this._gen++;

    // 既存の接続をクローズ
    this._intentionalClose = true;
    this._closeInternal();

    this._url = url;
    this._protocols = options.protocols;
    this._autoReconnect = options.autoReconnect ?? false;
    this._reconnectInterval = options.reconnectInterval ?? 3000;
    this._maxReconnects = options.maxReconnects ?? Infinity;
    this._binaryType = options.binaryType ?? "blob";
    this._staleAfter = options.staleAfter !== undefined && options.staleAfter > 0 ? options.staleAfter : 0;
    this._reconnectCount = 0;
    this._intentionalClose = false;

    this._doConnect();
  }

  send(data: string | ArrayBufferLike | Blob | ArrayBufferView): void {
    // never-throw (§3.6): 未接続での送信は例外ではなく error に流す。set send の
    // fire-and-forget 経路で例外が伝播するのを防ぐ。
    if (!this._ws || this._ws.readyState !== WS_OPEN) {
      this._setError({ message: "WebSocket is not connected." }, WCS_WEBSOCKET_ERROR_CODE.InvalidState);
      this._warnNotReady();
      return;
    }
    this._ws.send(data);
  }

  private _warnNotReady(): void {
    if (this._toldNotReady) return;
    this._toldNotReady = true;
    console.warn(
      "[@wcstack/websocket] [wcs/command-not-ready] send() was refused: the WebSocket is not connected, so the message is lost. " +
        "It goes to `error` too. Send once `connected` is true. (Said once until the WebSocket connects again.)",
      this._target,
    );
  }

  close(code?: number, reason?: string): void {
    if (this._stop(code, reason, false)) {
      // The socket was still connecting and is let go: its close event will not reach the core,
      // so the end is published now (timing-and-firing-contract §22).
      this._publishClosed();
    }
  }

  /**
   * Stops the connection: no reconnect, no stale watchdog, the socket closed. An open socket is
   * closed now and its close event publishes the end. A socket still connecting is let go instead
   * (unless `abortConnecting`): closing it before its handshake makes Chromium print "WebSocket is
   * closed before the connection is established." — on every route left right after it was
   * entered (docs/seam-apps.md, homeroom). Returns true when it let one go: its events no longer
   * reach the core, so the caller publishes the end.
   */
  private _stop(code: number | undefined, reason: string | undefined, abortConnecting: boolean): boolean {
    this._intentionalClose = true;
    this._clearReconnectTimer();
    this._clearStaleTimer();
    const ws = this._ws;
    if (ws === null) return false;
    if (abortConnecting || ws.readyState !== WS_CONNECTING) {
      ws.close(code, reason);
      return false;
    }
    this._removeListeners();
    this._ws = null;
    this._closeWhenOpen(ws, code, reason);
    return true;
  }

  /**
   * Closes a socket the core has let go while it was still connecting, once it opens; a socket
   * that fails to connect is just dropped. Nothing from it reaches the core any more.
   */
  private _closeWhenOpen(ws: WebSocket, code?: number, reason?: string): void {
    const drop = (): void => {
      ws.removeEventListener("open", open);
      ws.removeEventListener("error", drop);
      ws.removeEventListener("close", drop);
    };
    const open = (): void => {
      drop();
      try {
        ws.close(code, reason);
      } catch {
        // a code or reason the platform refuses must not leave the socket open
        ws.close();
      }
    };
    ws.addEventListener("open", open);
    ws.addEventListener("error", drop);
    ws.addEventListener("close", drop);
  }

  // --- Internal ---

  private _doConnect(): void {
    this._setLoading(true);
    this._setError(null);

    // 接続開始時点の世代を捕捉。dispose()/再 connect() 後に発火した古いソケット
    // イベントはこの gen が stale になり、状態を書き換えない（_onOpen ほかが
    // _socketGen と this._gen を突き合わせて判定する）。
    this._socketGen = this._gen;

    try {
      this._ws = this._protocols
        ? new WebSocket(this._url, this._protocols)
        : new WebSocket(this._url);
    } catch (e) {
      this._setLoading(false);
      this._setError(e, WCS_WEBSOCKET_ERROR_CODE.ConnectionError);
      return;
    }

    // Binary frames default to Blob; opt into ArrayBuffer for direct byte access.
    this._ws.binaryType = this._binaryType;

    this._setReadyState(WS_CONNECTING);

    this._ws.addEventListener("open", this._onOpen);
    this._ws.addEventListener("message", this._onMessage);
    this._ws.addEventListener("error", this._onError);
    this._ws.addEventListener("close", this._onClose);
  }

  private _onOpen = (): void => {
    if (this._socketGen !== this._gen) return;
    this._reconnectCount = 0;
    // ready again: a send refused in the next outage is said again
    this._toldNotReady = false;
    this._lastActivity = Date.now();
    this._armStale();
    this._setLoading(false);
    this._setConnected(true);
    this._setReadyState(WS_OPEN);
  };

  private _onMessage = (event: MessageEvent): void => {
    if (this._socketGen !== this._gen) return;
    this._lastActivity = Date.now();
    let data = event.data;
    // JSONの自動パース
    if (typeof data === "string") {
      try {
        data = JSON.parse(data);
      } catch {
        // テキストのまま
      }
    }
    this._setMessage(data);
  };

  private _onError = (event: Event): void => {
    if (this._socketGen !== this._gen) return;
    this._setError(event, WCS_WEBSOCKET_ERROR_CODE.ConnectionError);
  };

  private _onClose = (event: CloseEvent): void => {
    this._removeListeners();
    this._ws = null;
    if (this._socketGen !== this._gen) return;
    this._setConnected(false);
    this._setLoading(false);
    this._setReadyState(WS_CLOSED);

    // 異常クローズ時の自動再接続（正常終了 1000 は除外）
    if (!this._intentionalClose && this._autoReconnect && event.code !== 1000 && this._reconnectCount < this._maxReconnects) {
      this._scheduleReconnect();
    }
  };

  private _scheduleReconnect(): void {
    const gen = this._gen;
    this._clearReconnectTimer();
    this._reconnectTimer = setTimeout(() => {
      this._reconnectTimer = null;
      // dispose()/再 connect() でこの再接続が無効化されていたら何もしない。
      if (gen !== this._gen) return;
      this._reconnectCount++;
      this._doConnect();
    }, this._reconnectInterval);
  }

  // stale-after の見張り。開いている間、最後の open / メッセージから staleAfter ms 何も届かなければ、
  // 接続は失われたとみなす（docs/seam-apps.md、shift-desk: 閉じられずに死んだ接続 — スリープ・NAT・
  // proxy — に WebSocket は気づかず OPEN のまま、ページは "connected" と言い続けた）。タイマーは 1 本
  // だけ持ち、満了のたびに最後の活動からの残りで張り直す（メッセージごとに張り直さない）。
  private _armStale(): void {
    if (this._staleAfter === 0 || this._staleTimer !== null) return;
    this._staleTimer = setTimeout(this._checkStale, this._staleAfter);
  }

  private _checkStale = (): void => {
    this._staleTimer = null;
    const ws = this._ws;
    if (ws === null || this._readyState !== WS_OPEN) return;
    const idle = Date.now() - this._lastActivity;
    if (idle < this._staleAfter) {
      this._staleTimer = setTimeout(this._checkStale, this._staleAfter - idle);
      return;
    }
    // 失われたとみなし、異常なクローズと同じに扱う。半開きの TCP では閉じる手順が終わらないので、
    // ソケットはその場で手放し（イベントは外す）、終わりと理由を知らせ、auto-reconnect の規則で
    // つなぎ直す。
    this._removeListeners();
    this._ws = null;
    try {
      ws.close(4000, "stale");
    } catch {
      // a socket that cannot be closed any more is gone anyway
    }
    this._setConnected(false);
    this._setLoading(false);
    this._setReadyState(WS_CLOSED);
    this._setError({ message: `No message for ${this._staleAfter} ms: the connection is treated as lost.` }, WCS_WEBSOCKET_ERROR_CODE.ConnectionError);
    if (!this._intentionalClose && this._autoReconnect && this._reconnectCount < this._maxReconnects) {
      this._scheduleReconnect();
    }
  };

  private _clearStaleTimer(): void {
    if (this._staleTimer !== null) {
      clearTimeout(this._staleTimer);
      this._staleTimer = null;
    }
  }

  private _clearReconnectTimer(): void {
    if (this._reconnectTimer !== null) {
      clearTimeout(this._reconnectTimer);
      this._reconnectTimer = null;
    }
  }

  private _removeListeners(): void {
    if (!this._ws) {
      return;
    }

    this._ws.removeEventListener("open", this._onOpen);
    this._ws.removeEventListener("message", this._onMessage);
    this._ws.removeEventListener("error", this._onError);
    this._ws.removeEventListener("close", this._onClose);
  }

  private _closeInternal(): void {
    this._clearReconnectTimer();
    this._clearStaleTimer();
    const ws = this._ws;
    if (ws) {
      this._removeListeners();
      this._ws = null;
      if (ws.readyState === WS_OPEN) {
        ws.close();
      } else if (ws.readyState === WS_CONNECTING) {
        // a connect() replacing a socket still connecting (a url changed right after it was
        // set) lets it go: closing it now would make Chromium warn (see _stop)
        this._closeWhenOpen(ws);
      }
    }
    // 旧接続の状態をリセット（コンストラクタ例外時に stale 状態が残るのを防止）
    if (this._connected) {
      this._setConnected(false);
    }
    if (this._readyState !== WS_CLOSED) {
      this._setReadyState(WS_CLOSED);
    }
  }
}
